import {createSimulation,readout,PARAMS} from './model.js';
let graph=null,running=false,cancelled=false;
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function rawFile(file){let last;for(let attempt=1;attempt<=3;attempt++)try{const r=await fetch(new URL(file.url,import.meta.url),{cache:'force-cache'});if(!r.ok)throw Error(`HTTP ${r.status}`);const bytes=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(bytes.byteLength!==file.rawBytes)throw Error('invalid data length');const digest=await crypto.subtle.digest('SHA-256',bytes);const hash=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==file.sha256)throw Error('integrity check failed');return bytes}catch(error){last=error;if(attempt<3)await pause(attempt*350)}throw Error(`Could not download ${file.name} after 3 attempts: ${last.message}`)}
async function load(){const r=await fetch(new URL('data/manifest.json',import.meta.url),{cache:'force-cache'});if(!r.ok)throw Error('Connectome manifest unavailable');const m=await r.json();const targets=new Uint32Array(m.connections),counts=new Uint32Array(m.connections);let offsets,signs,loaded=0,next=0;async function consume(file){const bytes=await rawFile(file);if(file.name==='offsets')offsets=new Uint32Array(bytes);else if(file.name==='signs')signs=new Int8Array(bytes);else{const index=Number(file.name.split('-')[1])*2000000;(file.name.startsWith('targets')?targets:counts).set(new Uint32Array(bytes),index)}loaded+=file.bytes;postMessage({type:'loading',progress:loaded/m.downloadBytes,loaded,total:m.downloadBytes})}async function loader(){while(true){const i=next++;if(i>=m.files.length)return;await consume(m.files[i])}}await Promise.all(Array.from({length:4},loader));if(offsets.length!==m.neurons+1||offsets[m.neurons]!==m.connections)throw Error('Invalid graph offsets');graph={n:m.neurons,offsets,targets,counts,signs,groups:m.groups};postMessage({type:'ready',manifest:m})}
self.onmessage=async({data})=>{try{if(data.type==='load'){if(!graph)await load();return}if(data.type==='cancel'){cancelled=true;return}if(data.type==='run'){if(!graph)throw Error('Brain not loaded');if(running)throw Error('An encounter is already running');running=true;cancelled=false;const sim=createSimulation(graph,data.profile,{seed:data.seed||703});const view=new Set(data.view),raster=new Set(data.raster);let s;while(!cancelled){const spikes=[],rasterSpikes=[];const start=performance.now();do{s=sim.tick();for(const i of s.fired){if(view.has(i))spikes.push(i);if(raster.has(i))rasterSpikes.push([s.ms,i])}}while(!s.done&&performance.now()-start<35);postMessage({type:'activity',id:data.id,ms:s.ms,total:s.total,active:s.active,spikes,rasterSpikes,outputHz:s.outputHz,groupHz:s.groupHz});if(s.done)break;await new Promise(r=>setTimeout(r,0))}running=false;if(!cancelled)postMessage({type:'result',id:data.id,outcome:readout(s.outputHz),outputHz:s.outputHz,groupHz:s.groupHz,total:s.total,seed:data.seed||703,parameters:PARAMS})}}catch(error){running=false;postMessage({type:'error',message:error.message})}};
